def transform(grid):
    """Fill each hollow rectangular frame: interiors become 7 (demo indicates 3-frame maps to 2)."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 4) or (r, c) in seen:
                continue
            # Find same-color 4-connected component.
            stack = [(r, c)]; seen.add((r, c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            rs=[y for y,x in cells]; cs=[x for y,x in cells]
            top,bottom,left,right=min(rs),max(rs),min(cs),max(cs)
            if len(cells) != 2*((bottom-top+1)+(right-left+1))-4:
                continue
            if not all(grid[top][x]==color and grid[bottom][x]==color for x in range(left,right+1)):
                continue
            if not all(grid[y][left]==color and grid[y][right]==color for y in range(top,bottom+1)):
                continue
            fill = 2 if color == 3 else 7
            for y in range(top+1,bottom):
                for x in range(left+1,right):
                    out[y][x]=fill
    return out
